head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.vScrenID = "ULDSTF05938.xml";
scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.Dd = "", scwin.p_Isur_cd = "", scwin.p_Isur_nm = "";
scwin.fr_MktId = $c.lc.fn_getMktId();
scwin.trsIdx; // insert, update 구분

scwin.isFirstLoad = false;
scwin.delYn = false;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_get_isu_cd = function() {
    if (edt_Dd.text.length != 8) {
        $c.win.alert("[거래부진 폐지일]을 정확히 입력하세요.");
        return false;
    }
    if (edt_STRT_DD.text.length != 8) {
        $c.win.alert("[거래시작일]을 정확히 입력하세요.");
        return false;
    }
    if (edt_LIST_DD.text.length != 8) {
        $c.win.alert("[상장제한일]을 정확히 입력하세요.");
        return false;
    }
    var url = "/listingCommon.do?SCREN_ID=ULDSTF05938.gfm&SCREN_PROCES_TP_CD=01&method=listGeneralForDynamicName" + "&outputMessageId=CODE_ELW_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwdelistcaunt.select.lpclose.condition";
    url += "&{P}PROC_DD=" + edt_Dd.getValue();
    url += "&{P}STRT_DD=" + edt_STRT_DD.getValue();
    url += "&{P}LIST_DD=" + edt_LIST_DD.getValue();
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.reset();
    $c.cm.ShowWin(grd_isu);
};
scwin.fn_search = function() {
    if (scwin.fr_bz_procs_no != "") {
        var url = "/Delisting.do?method=searchDelList" + "&DIV_IDX=" + DIV_IDX_DELLIST_MST + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Mst.DataID = encodeURI(url);
        dts_Mst.reset();
        url = "/Delisting.do?method=searchDelList" + "&DIV_IDX=" + DIV_IDX_DELLIST_DTL + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        dts_Isu.DataID = encodeURI(url);
        dts_Isu.reset();
    }
};
scwin.fn_new_onload = function() {
    var url = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELLIST_MST_INOUT";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //dts_Mst.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELLIST_MST_INOUT";
    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();
    edt_Dd.setValue($c.ut.cGetToday("yyyymmdd"));
    edt_END_DD.setValue(edt_Dd.getValue());
    scwin.fn_setDate();
    scwin.fn_get_isu_cd();
};
scwin.fn_get_rsn_cd = function() {
    var url = "/listingCommon.do?method=listCode&inputMessageId=LISTING_CODE_IN&outputMessageId=LISTING_CODE_OUT&MKT=" + scwin.Mkt_id + "&RSN=" + "05";
    dts_Rsn.DataID = encodeURI(url);
    dts_Rsn.reset();
};
scwin.fn_CheckForm = function() {
    if (dts_Isu.getTotalRow() == 0) {
        $c.win.alert("[상장폐지종목]을 선택하세요.");
        return false;
    }
    if (!$c.lc.checkDdTm("DD", edt_DelistDd, "상장폐지", false)) return false;
    if (!$c.stf.checkEmptyValue(txb_GrndRegulNm, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txb_GrndRegulNm, 200, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txa_Remk, 2000, "기타")) return false;
    if (scwin.fn_duplicate_check()) return false;
    return true;
};
scwin.fn_duplicate_check = function() {
    var Isus = "";
    if (dts_Isu.getTotalRow() == 0) return false;
    for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {
        Isus += dts_Isu.getCellData(i, "ISU_CD") + ",";
    }
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=DELLIST_MST_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.dellistdtl.duplicatecheck.select" + "&{P}param01=" + $c.stf.getObjectValue(edt_DelistDd) + "&{P}param02=" + Isus + "&{P}param03=" + scwin.fr_bz_procs_no + "&{P}param04=" + scwin.fr_bz_procs_no;
    dts_DUP_CHK.DataID = encodeURI(url);
    dts_DUP_CHK.reset();
    if (dts_DUP_CHK.getTotalRow() > 0) {
        $c.stf.showObj(btn_deleteRow, true);
        $c.win.alert("'" + dts_DUP_CHK.getCellData(1, "ISU_CD") + "'" + " 종목이 \n" + "'" + dts_DUP_CHK.getCellData(1, "DELIST_RSN_NM") + "'" + " 사유로 저장되어 있습니다.");
        return true;
    } else {
        $c.stf.showObj(btn_deleteRow, false);
    }
    return false;
};
scwin.fn_save_trs = function() {
    // 매매거래정지종목은 매번 업무처리 번호를 세팅함
    // 종목별 변경이 있을수 있기 때문
    for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_Isu.NameString(i, "BZ_PROCS_NO") = fr_bz_procs_no;*/
        X = scwin.fr_bz_procs_no;
    }


    // ELW는 항상  종목별기준으로 처리함
    // 1 : 종목별 , 2 : 법인별

    dts_Mst.setCellData(dts_Mst.getRowPosition(), "MKTACT_APPL_OBJ_TP_CD", "1");
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "DELIST_RSN_CD", dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "CODE"));
    var vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx == TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx == TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.Action = $c.lc.fn_encodeNSession("/Delisting.do?method=saveDelList&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD);
    trs.KeyName = "toinb_dataid4";
    trs.KeyValue = "JSP(I: dtsParm1= dts_Mst , I:dtsParm2= dts_Isu)";
    trs.Parameters = "TRS_IDX=" + scwin.trsIdx + ",BZ_PROCS_NO=" + scwin.fr_bz_procs_no + ",COUNT=2" + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_314 + ",DIV_IDX[0]=" + DIV_IDX_DELLIST_MST + ",DIV_IDX[1]=" + DIV_IDX_DELLIST_DTL;
    trs.Post();
};
scwin.fn_save = function() {
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        scwin.fr_bz_procs_no = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", "99999");
            scwin.fn_save_trs();
        }
    }
};
scwin.fn_update = function() {
    if (scwin.fn_CheckForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lc.fn_isProcess('U')) return;
        scwin.fn_save_trs();
    }
};
scwin.fn_delete = function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.fn_save_trs();
};
scwin.fn_ElwInst = function() {
    dts_ElwInst.DataID = "/CodeAction.do?method=listWrntCd&For=";
    dts_ElwInst.Reset();
};
scwin.fn_dscl = async function() {
    if (scwin.fn_duplicate_check()) return;

    //수정한 것이 있으면 체크 됨.(종목제외)
    if ($c.cp.isModified(dts_Mst) || $c.cp.isModified(dts_Rsn) || scwin.delYn == true) {
        $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_ElwInst();
    //dts_DISC.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    var cont = 1;
    for (var i = 1; i <= dts_ElwInst.getTotalRow(); i++) {
        var pLpMbtNm = "";
        var pIsuNm = "";
        var pCheck = false;
        var pcount = 0;
        var pLenStr = 0;
        var cnt = 1;
        for (var k = 1; k <= dts_Isu.getTotalRow(); k++) {
            if (dts_ElwInst.getCellData(i, "VALUE") == dts_Isu.getCellData(k, "INFO_ISUR_CD")) {
                pLpMbtNm = dts_ElwInst.getCellData(i, "TEXT");
                if (pcount > 0) {
                    pIsuNm = pIsuNm + ",";
                }
                if (pcount % 4 == 0 && pcount != 0) pIsuNm = pIsuNm + "\n" + dts_Isu.getCellData(k, "ISU_NM");

                else pIsuNm = pIsuNm + dts_Isu.getCellData(k, "ISU_NM");
                pcount++;
                pCheck = true;
            }
        }
        if (pCheck) {
            dts_DISC.insertRow();
            dts_DISC.setCellData(cont, "INFO_COM_NM", pLpMbtNm);
            dts_DISC.setCellData(cont, "ISU_NM", pIsuNm);
            cont++;
        }
    }
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68955F";
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = "99999";
        arr[3] = '1';
        arr[4] = '';
        arr[5] = '거래 부진에 의한 상장폐지';
        $c.stf.CopyDataSet(dts_Isu, param_dts_isu);
        $c.stf.CopyDataSet(dts_Mst, param_dts_mst);
        $c.stf.CopyDataSet(dts_DISC, param_dts2);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "DELIST_RSN_NM", cmb_Rsn_Cd.getText());
        //	param_dts_mst.NameString(param_dts_mst.RowPosition, "COM_NM") = p_Isur_nm ;	//발행사명


        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 740 + 5;
    var hgt = 790 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_setDate = function() {
    var url = "/listingCommon.do?SCREN_ID=ULDSTF45001.gfm&SCREN_PROCES_TP_CD=01&method=listGeneralForDynamicName" + "&outputMessageId=CODE_M_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwdelistcaunt.select.date";
    url += "&{P}DATE1=" + scwin.getStrtDate();
    url += "&{P}DATE2=" + scwin.getListDate();
    dts_date.DataID = encodeURI(url);
    dts_date.reset();
    for (var i = 1; i <= dts_date.getTotalRow(); i++) {
        if (dts_date.getCellData(i, 'CD_ID') == '1') {
            edt_STRT_DD.setValue(dts_date.getCellData(i, 'VALUE'));
        } else if (dts_date.getCellData(i, 'CD_ID') == '2') {
            edt_LIST_DD.setValue(dts_date.getCellData(i, 'VALUE'));
        }
    }
};
scwin.getStrtDate = function() {
    var yyyymmdd = edt_Dd.getValue();
    var yyyy = yyyymmdd.substring(0, 4);
    var mm = yyyymmdd.substring(4, 6);
    var dd = yyyymmdd.substring(6, 8);
    if (mm == 01) {
        mm = 12;
        yyyy = yyyy - 1;
    } else {
        mm = mm - 1;
    }
    return '' + yyyy + $c.ut.cGetZero(mm, 2) + dd;
};
scwin.getListDate = function() {
    var yyyymmdd = edt_Dd.getValue();
    var yyyy = yyyymmdd.substring(0, 4);
    var mm = yyyymmdd.substring(4, 6);
    var dd = yyyymmdd.substring(6, 8);
    if (mm == 02) {
        mm = 12;
        yyyy = yyyy - 1;
    } else if (mm == 01) {
        mm = 11;
        yyyy = yyyy - 1;
    } else {
        mm = mm - 2;
    }
    return '' + yyyy + $c.ut.cGetZero(mm, 2) + dd;
};
scwin.fn_drft = function() {

};
scwin.fn_makt = function() {

};
scwin.trs_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_OnSuccess = async function() {
    scwin.delYn = false;
    $c.lc.fn_alertMsg('S');
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_search();
    }
};
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    if (scwin.fr_bz_procs_no == "") {
        dts_Mst.insertRow();
    }

    // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
    if (scwin.fr_bz_procs_no == "") {
        buttonSet.setInsertStatus();
    } else {
        $c.stf.setButtonSetWithDate(edt_DelistDd, false);
    }
    scwin.isFirstLoad = true;
    if (scwin.fr_bz_procs_no == "") {
        cmb_Rsn_Cd.BindColVal = "690020";
        txb_GrndRegulNm.setValue(dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "REGL"));
    } else {
        cmb_Rsn_Cd.BindColVal = dts_Mst.getCellData(dts_Mst.getRowPosition(), "DELIST_RSN_CD");
    }
    scwin.isFirstLoad = false;
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_DelistDd_onclick = function() {
    txa_Remk.Text = "";
    edt_DelistDd.focus();
    popUpCalendar2(edt_DelistDd);
};
scwin.cmb_Rsn_Cd_OnSelChange2 = function() {
    if (scwin.isFirstLoad) return;
    txb_GrndRegulNm.setValue(dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "REGL"));
    //alert(dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE") + "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "NAME")+ "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL")) ;

};
scwin.cmb_Rsn_Cd_OnSelected = function() {

};
scwin.btn_Dd_onclick = function() {
    if (scwin.fr_bz_procs_no != "") return;
    popUpCalendar2(edt_Dd);
};
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    var count = dts_Isu.getTotalRow();
    for (var i = 1; i < count + 1; i++) {
        dts_Isu.setCellData(i, "ELW_RGHT_TP_KIND_CD", 'F');
    }
    $c.cm.CloseWin(rowcount, grd_isu);
};
scwin.gform_onload = function() {
    var fnc = $c.frame.path("../").scwin.fn_GetPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
    var arrPar = new Array();
    if (fnc != undefined) {
        fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
        scwin.Secugrp_id = (arrPar.length >= 1 ? arrPar[0] : ""); // 증권그룹ID
        scwin.Mkt_id = (arrPar.length >= 2 ? arrPar[1] : ""); // 시장구분코드
        scwin.fr_bz_procs_no = (arrPar.length >= 3 ? arrPar[2] : ""); // 업무처리번호(수정시만 유효)
        scwin.Dd = (arrPar.length >= 4 ? arrPar[3] : ""); // 최종거래일 또는 당일자	

    }
    scwin.fn_get_rsn_cd();

    //alert( "Isur_cd =  " +Isur_cd + "\n"  + " Isur_nm = " + Isur_nm + "\n" + "  Secugrp_id = " + Secugrp_id + "\n" + 
    //		 "Mkt_id =  " +Mkt_id + "\n" + " fr_bz_procs_no = " + fr_bz_procs_no+ "\n"  ) ;

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성

    buttonSet.setCopyInfo(btn_Search, fn_get_isu_cd, btn_Save); // 조회

    edt_Dd.setValue(scwin.Dd);
    if (scwin.fr_bz_procs_no != "") {
        // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
        edt_Dd.setReadOnly(true);
        scwin.fn_search();
    } else {
        edt_Dd.setReadOnly(false);
        scwin.fn_new_onload(); // 신규작성시 호출

    }

    /* 기존 : 로그인자의 부서 소속을 기준으로 한 시장구분코드가 9(시장전체공통)인 경우 달력이 표기
          수정 : 달력 전체 미표시로 수정 */
    //if(fr_MktId != '9'){
    $c.stf.showObj(btn_Dd, false);
    $c.stf.showObj(img_STRT_DD, false);
    $c.stf.showObj(img_LIST_DD, false);
    $c.stf.showObj(btn_deleteRow, false);
    //}

    $c.libRoundPanel.PanelToGroupBox(panel_3);
    $c.libRoundPanel.PanelToGroupBox(panel_1);
};
scwin.btn_deleteRow_onclick = function() {
    if (confirm('선택한 종목을 삭제하시겠습니까?')) {
        var count = dts_Isu.getTotalRow();
        for (var i = count; i > 0; i--) {
            if (dts_Isu.getCellData(i, "ELW_RGHT_TP_KIND_CD") == 'T') {
                $c.cp.removeRow(dts_Isu, i);
                scwin.delYn = true;
            }
        }
    }
};
scwin.edt_DelistDd_OnKillFocus = function() {
    var cnt = dts_Isu.getTotalRow();
    txa_Remk.Text = "상기 " + cnt + "종목의 주식워런트 증권은 직전 1개월간 누적거래량이 상장증권수의 1%에 미달하는 거래부진종목으로서 LP가 전부보유한 사실이 ";
    txa_Remk.Text += "확인되어 " + $c.stf.getObjectValue(edt_DelistDd).substring(0, 4) + "년 ";
    txa_Remk.Text += $c.stf.getObjectValue(edt_DelistDd).substring(4, 6) + "월 ";
    txa_Remk.Text += $c.stf.getObjectValue(edt_DelistDd).substring(6, 8) + "일에 상장폐지됨을 알려드립니다.";
};
scwin.img_STRT_DD_onclick = function() {
    popUpCalendar2(edt_STRT_DD);
};
scwin.img_LIST_DD_onclick = function() {
    popUpCalendar2(edt_LIST_DD);
};
scwin.edt_Dd_OnKillFocus = function() {
    scwin.fn_setDate();
    edt_END_DD.setValue(edt_Dd.getValue());
};
